import{_ as e,c as o,o as i,ae as n}from"./chunks/framework.Bi6zybwU.js";const h=JSON.parse('{"title":"Import CSV File to an Existing Table","description":"Import CSV File to an Existing Table","frontmatter":{"title":"Import CSV File to an Existing Table","description":"Import CSV File to an Existing Table"},"headers":[],"relativePath":"guide/import-export/import-csv-file-to-an-existing-table.md","filePath":"guide/import-export/import-csv-file-to-an-existing-table.md"}'),a={name:"guide/import-export/import-csv-file-to-an-existing-table.md"};function l(s,t,r,p,m,g){return i(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="import-csv-file-to-an-existing-table" tabindex="-1">Import CSV File to an Existing Table <a class="header-anchor" href="#import-csv-file-to-an-existing-table" aria-label="Permalink to &quot;Import CSV File to an Existing Table&quot;">​</a></h1><p>You can easily import a CSV file (Comma Separated Values) to an existing table by following a few steps.</p><ul><li>First, go to the <strong>Ninja Tables dashboard →</strong> and open an <strong>existing</strong> <strong>table</strong> where you want to import a CSV file.</li><li>Now go to the **Import-Export **tab of that table.</li><li>Here, you will find a <strong>Choose</strong> <strong>file</strong> option, and you can upload only <strong>CSV</strong>(Comma Separated Value) files.</li><li>Replace Existing Data. When you <strong>Enable Replace Existing Data</strong>, the same row of the CSV file will be replaced with the existing Table. <img src="https://ninjatables.com/wp-content/uploads/2022/09/01-scaled.webp" alt="Import-Export tab"></li><li>One thing to remember is that the Header Structure of the CSV file you intend to import must match the <strong>Column</strong> <strong>Key</strong> of the existing table. Let&#39;s have a look at an example for a better understanding-</li><li>Now, choose the third column, whose heading is <strong>last_Name</strong>, and click the <strong>Edit</strong> icon next to the column name. (Same as with other columns). <img src="https://ninjatables.com/wp-content/uploads/2023/01/import-CSV-file-to-an-Existing-table-3-1024x488.png" alt="Column Name"></li><li>A pop-up window will appear displaying the <strong>Column</strong> <strong>Key</strong> of that particular <strong>Column</strong> <strong>Name</strong>.</li><li>Column Key for the third column is <strong>lastname</strong> in this case. It must be identical to the third column of the CSV file that you intend to import. Otherwise, importing both files will not work together. <img src="https://ninjatables.com/wp-content/uploads/2022/09/02-1-1024x402.webp" alt="Column Key"></li><li>And now, take a look at the CSV file you&#39;re about to import.</li><li>As you can see, the names of all columns are the same as the Existing table Column Key. <img src="https://ninjatables.com/wp-content/uploads/2023/01/import-CSV-file-to-an-Existing-table-5-1024x460.png" alt="column name same as column key in table"></li><li>You can now go to the existing table&#39;s **Import-Export **tab and upload a file by clicking on the <strong>Choose</strong> <strong>File</strong> button.</li><li>When you&#39;re finished uploading the file, click the <strong>Import</strong> <strong>from</strong> <strong>CSV</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2022/09/03-1-scaled.webp" alt="Import from CSV button"></li><li>Go back to the Existing table and check to confirm if the Imported CSV file is working properly.</li><li>To import data from a CSV file into an existing table, the header structure of the CSV file has to be identical to the current table header information. You can simply download the sample CSV file by clicking on the <strong>Download Sample CSV</strong> button to find out about your CSV file header structure. These are a few simple steps to easily import CSV files to an Existing Table!</li></ul>',3)])])}const u=e(a,[["render",l]]);export{h as __pageData,u as default};
